update country_flag_history set notes_fr = 'Couleurs des étudiants libéraux et des volontaires de Lützow, le noir-rouge-or est adopté en 1848 par la Diète et le Parlement de Francfort comme symbole de l''unité allemande, puis abandonné après l''échec de la révolution.', notes_en = 'The colours of liberal students and the Lützow volunteers, black-red-gold was adopted in 1848 by the Diet and the Frankfurt Parliament as the symbol of German unity, then dropped after the revolution failed.', image_url = '/flags/history/de-0000.svg' where id = 1529 and iso_code = 'de';
update country_flag_history set notes_fr = 'Le noir-blanc-rouge naît en 1867 pour la Confédération de l''Allemagne du Nord : il associe le noir et blanc de la Prusse au rouge et blanc des villes hanséatiques.', notes_en = 'Black-white-red was created in 1867 for the North German Confederation: it combined Prussia''s black and white with the red and white of the Hanseatic cities.', image_url = '/flags/history/de-0000-2.svg' where id = 1530 and iso_code = 'de';
update country_flag_history set notes_fr = 'Proclamé à Versailles le 18 janvier 1871, l''Empire allemand garde le noir-blanc-rouge, officialisé comme drapeau national en 1892.', notes_en = 'Proclaimed at Versailles on 18 January 1871, the German Empire kept black-white-red, made the official national flag in 1892.', image_url = '/flags/history/de-0000-2.svg' where id = 1531 and iso_code = 'de';
update country_flag_history set notes_fr = 'Après l''abdication de Guillaume II, la jeune république conserve provisoirement le noir-blanc-rouge, jusqu''à l''entrée en vigueur de la Constitution de Weimar.', notes_en = 'After Wilhelm II abdicated, the young republic kept black-white-red for the time being, until the Weimar Constitution came into force.', image_url = '/flags/history/de-0000-2.svg' where id = 1532 and iso_code = 'de';
update country_flag_history set notes_fr = 'La Constitution de Weimar reprend le noir-rouge-or de 1848, mais le pavillon marchand garde le noir-blanc-rouge avec un canton aux nouvelles couleurs : la question du drapeau divise la république.', notes_en = 'The Weimar Constitution brought back the 1848 black-red-gold, but the merchant flag kept black-white-red with a canton in the new colours: the flag question split the republic.', image_url = '/flags/history/de-1919.svg' where id = 1533 and iso_code = 'de';
update country_flag_history set notes_fr = 'Le 12 mars 1933, Hitler rétablit le noir-blanc-rouge impérial, arboré aux côtés du drapeau du parti nazi.', notes_en = 'On 12 March 1933 Hitler restored the imperial black-white-red, flown alongside the Nazi party flag.', image_url = '/flags/history/de-1933.svg' where id = 1534 and iso_code = 'de';
update country_flag_history set notes_fr = 'Les lois de Nuremberg du 15 septembre 1935 font du drapeau du parti nazi l''unique drapeau national. Son usage est aujourd''hui interdit en Allemagne en dehors d''un cadre historique ou éducatif.', notes_en = 'The Nuremberg Laws of 15 September 1935 made the Nazi party flag the sole national flag. Its use is now banned in Germany outside historical or educational contexts.', image_url = '/flags/history/de-1935.svg' where id = 1535 and iso_code = 'de';
update country_flag_history set date_start = '1946-01-01', label_fr = 'Occupation alliée : pavillon « C » des navires', label_en = 'Allied occupation: "C" pennant for ships', notes_fr = 'Sous l''occupation, l''Allemagne n''a plus de drapeau national ; ses navires marchands arborent un pavillon de signalisation « C » modifié, à queue d''aronde.', notes_en = 'Under occupation Germany had no national flag; its merchant ships flew a modified, swallow-tailed "C" signal flag.' where id = 2343 and iso_code = 'de';
update country_flag_history set notes_fr = 'La Loi fondamentale du 23 mai 1949 rétablit le noir-rouge-or de la république de Weimar ; il devient le drapeau de l''Allemagne réunifiée en 1990.', notes_en = 'The Basic Law of 23 May 1949 restored the black-red-gold of the Weimar Republic; it became the flag of reunified Germany in 1990.', image_url = 'https://flagcdn.com/de.svg' where id = 1536 and iso_code = 'de';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('de', '/flags/history/de-1400.svg', '1400-01-01', '1806-08-06', 'Saint-Empire romain germanique', 'Holy Roman Empire', 'Bannière impériale à l''aigle bicéphale noir sur fond or, emblème de l''empereur du XVe siècle jusqu''à la dissolution de l''Empire en 1806.', 'The imperial banner with a black double-headed eagle on gold, the emperor''s emblem from the 15th century until the Empire was dissolved in 1806.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('de', '/flags/history/de-1947-2.svg', '1947-12-15', '1956-12-31', 'Protectorat de la Sarre', 'Saar Protectorate', 'Placée sous protectorat français, la Sarre adopte une croix scandinave blanche sur fond bleu et rouge ; elle rejoint la RFA le 1er janvier 1957 après un référendum.', 'Under a French protectorate, the Saar adopted a white Nordic cross on blue and red; it joined West Germany on 1 January 1957 after a referendum.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('de', '/flags/history/de-1959.svg', '1959-10-01', '1990-10-03', 'République démocratique allemande', 'German Democratic Republic', 'À partir de 1959, la RDA ajoute au noir-rouge-or ses armoiries (marteau et compas dans une couronne d''épis) pour se distinguer de la RFA. Le drapeau disparaît avec la réunification du 3 octobre 1990.', 'From 1959 East Germany added its arms (hammer and compass in a wreath of wheat) to black-red-gold to set itself apart from West Germany. The flag disappeared with reunification on 3 October 1990.');
